// Unifica trigger automático (Drive) y manual (Webhook)
// El trigger de Drive entrega: id, name, mimeType
// El webhook manual puede enviar: { file_id, file_name } en body
const fromDrive   = $('Drive — Nuevo Informe XLSX').first?.()?.json;
const fromWebhook = $('Webhook Manual REPORTER').first?.()?.json;

const src = fromDrive?.id ? fromDrive : (fromWebhook?.body || fromWebhook || {});

const fileId   = src.id   || src.file_id   || null;
const fileName = src.name || src.file_name || 'informe.xlsx';

if (!fileId) throw new Error('No se recibió file_id. Asegúrate de pasar { file_id, file_name } en el body del webhook manual.');

// Extraer post_id numérico del nombre del archivo
// Formato: PostAnalytics_NombreAutor_7430670067249340417.xlsx
const match = fileName.match(/(\d{10,22})(?:\.[a-z]+)?$/);
const postId = match ? match[1] : null;

return [{ json: { fileId, fileName, postId } }];

// ─── Normalizar métricas del Sheet de Rendimiento ─────────────────────────
// LinkedIn XLSX Sheet 0: Post performance
// Columnas típicas (pueden estar en EN o ES):
//   Created date | Content | Content type | Impressions | Views | Unique views
//   Clicks | Likes | Comments | Reposts | Follows | CTR | Engagement rate
//   o en español: Fecha | Contenido | Tipo | Impresiones | Vistas únicas...

const postId   = $('Unificar Trigger').first().json.postId;
const fileName = $('Unificar Trigger').first().json.fileName;

function num(v) {
  if (v === null || v === undefined || v === '') return 0;
  return parseFloat(String(v).replace(/,/g, '').replace(/%$/, '')) || 0;
}
function pct(v) {
  const n = num(v);
  // LinkedIn puede entregar CTR como 0.042 o como 4.2
  return n > 1 ? Math.round(n * 100) / 10000 : n;
}

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { _sin_datos: true, fileName } }];

// Detectar nombres de columna con tolerancia a idioma y versión
function col(row, ...candidates) {
  for (const c of candidates) {
    const key = Object.keys(row).find(k => k.toLowerCase().includes(c.toLowerCase()));
    if (key && row[key] !== undefined && row[key] !== '') return row[key];
  }
  return '';
}

const posts = rows
  .filter(row => Object.keys(row).length > 2)  // ignorar filas vacías
  .map(row => {
    const impresiones = num(col(row, 'impressions', 'impresiones', 'views', 'vistas'));
    const vistasUnicas = num(col(row, 'unique views', 'vistas únicas', 'unique_views'));
    const clics        = num(col(row, 'clicks', 'clics'));
    const likes        = num(col(row, 'likes', 'reactions', 'me gusta', 'reacciones'));
    const comentarios  = num(col(row, 'comments', 'comentarios'));
    const compartidos  = num(col(row, 'reposts', 'shares', 'compartidos'));
    const seguidores   = num(col(row, 'follows', 'seguidores', 'new followers'));
    const ctr_raw      = col(row, 'click through rate', 'ctr', 'click rate');
    const er_raw       = col(row, 'engagement rate', 'tasa de interacción', 'engagement');

    let ctr = pct(ctr_raw);
    if (ctr === 0 && impresiones > 0) ctr = clics / impresiones;

    let er = pct(er_raw);
    if (er === 0 && impresiones > 0) {
      er = (likes + comentarios + compartidos + clics) / impresiones;
    }

    const totalInteracciones = likes + comentarios + compartidos + clics;

    const fechaRaw = col(row, 'created', 'date', 'fecha', 'published');
    const tipoRaw  = col(row, 'content type', 'tipo', 'type', 'format');
    const contenido = String(col(row, 'content', 'contenido', 'text', 'post') || '').substring(0, 300);

    return {
      post_id:              postId,
      archivo:              fileName,
      fecha_publicacion:    fechaRaw,
      tipo:                 tipoRaw,
      contenido_preview:    contenido,
      impresiones:          impresiones,
      vistas_unicas:        vistasUnicas,
      clics:                clics,
      likes:                likes,
      comentarios:          comentarios,
      compartidos:          compartidos,
      nuevos_seguidores:    seguidores,
      ctr_pct:              Math.round(ctr * 10000) / 100,
      engagement_rate:      Math.round(er * 10000) / 10000,
      total_interacciones:  totalInteracciones,
      fecha_importacion:    new Date().toISOString().split('T')[0]
    };
  });

return posts.length > 0
  ? posts.map(p => ({ json: p }))
  : [{ json: { _sin_datos: true, fileName } }];

// ─── Normalizar demografía de todos los sheets en un solo output ──────────
// Recibe items de los 5 sheets de demografía, concatenados
const postId   = $('Unificar Trigger').first().json.postId;
const fileName = $('Unificar Trigger').first().json.fileName;
const hoy      = new Date().toISOString().split('T')[0];

// Detectar de cuál nodo vienen los items
const sheetLabels = [
  { node: 'Leer Sheet Función',   label: 'Función laboral' },
  { node: 'Leer Sheet Industria', label: 'Industria' },
  { node: 'Leer Sheet Senioridad',label: 'Senioridad' },
  { node: 'Leer Sheet Geografía', label: 'Ubicación' },
  { node: 'Leer Sheet Empresa',   label: 'Tamaño empresa' },
];

const result = [];

for (const { node, label } of sheetLabels) {
  let rows;
  try { rows = $(node).all().map(i => i.json); }
  catch(e) { continue; }  // sheet puede no existir en algunos exports

  for (const row of rows) {
    const keys = Object.keys(row).filter(k => row[k] !== undefined && row[k] !== '');
    if (keys.length < 2) continue;

    // Primera columna = nombre del segmento, segunda = porcentaje
    const segmento   = String(row[keys[0]] || '').trim();
    const pctRaw     = row[keys[1]] || row[keys.find(k => k.toLowerCase().includes('%') || k.toLowerCase().includes('pct') || k.toLowerCase().includes('percent')) || keys[1]] || 0;
    const porcentaje = parseFloat(String(pctRaw).replace(/%/,'').replace(',','.')) || 0;

    if (!segmento) continue;

    result.push({
      post_id:           postId,
      archivo:           fileName,
      categoria:         label,
      segmento:          segmento,
      porcentaje:        porcentaje > 1 ? Math.round(porcentaje * 100) / 100 : Math.round(porcentaje * 10000) / 100,
      fecha_importacion: hoy
    });
  }
}

if (!result.length) return [{ json: { _sin_demog: true, post_id: postId } }];
return result.map(r => ({ json: r }));

// Consolidar resultados de ambas ramas para la notificación
const trigger = $('Unificar Trigger').first().json;
const metItems = $('Upsert Metricas Sheet').all();
const demItems = $('Upsert Demografía Sheet').all();

// Extraer métricas del primer post indexado
const m = metItems[0]?.json || {};

const er   = parseFloat(m.engagement_rate || 0);
const erPct = (er * 100).toFixed(2);

return [{ json: {
  post_id:          trigger.postId,
  archivo:          trigger.fileName,
  impresiones:      m.impresiones     || m.views || 0,
  likes:            m.likes           || 0,
  comentarios:      m.comentarios     || m.comments || 0,
  compartidos:      m.compartidos     || m.reposts || 0,
  engagement_rate:  erPct,
  ctr_pct:          m.ctr_pct         || 0,
  vistas_unicas:    m.vistas_unicas   || 0,
  total_demog_rows: demItems.length,
  fecha_importacion: new Date().toISOString().split('T')[0]
}}];
